def decode(values):
    # Validate each byte is a strict integer in 0..255 and not a bool
    for v in values:
        if not isinstance(v, int) or isinstance(v, bool) or not (0 <= v <= 255):
            raise ValueError("invalid byte")
    # Must have even number of bytes (count,value pairs)
    if len(values) % 2:
        raise ValueError("incomplete run")
    result = []
    for i in range(0, len(values), 2):
        count, value = values[i], values[i + 1]
        # Count must be a strict positive integer
        if not isinstance(count, int) or isinstance(count, bool) or count <= 0:
            raise ValueError("zero or invalid run count")
        # Value already validated above
        result.extend([value] * count)
    return result

